INSERT INTO `AI_ARTICLE` (`ARTICLE_ID`, `CLUB_ID`, `SESSION_ID`, `MATCH_ID`, `ARTICLE_TYPE`, `TITLE`, `SUMMARY`, `CONTENT`, `MODEL_NAME`, `PROMPT_VERSION`, `INSIGHT_RULE_VERSION`, `STATUS`, `PUBLISHED_YN`, `PUBLISHED_AT`, `PARENT_ARTICLE_ID`, `GENERATION_NO`, `REQUEST_JSON`, `RESPONSE_JSON`, `ERROR_MESSAGE`, `UPDATED_AT`, `CREATED_AT`) VALUES (1,1,1,NULL,'PRE_MATCH','7월 5일, YPR 기록의 첫 페이지','7월 5일 일요일, YPR 19명이 3개 팀으로 나뉘어 맞붙는다. 오늘부터 모든 경기 기록이 쌓이기 시작한다.','7월 5일 일요일, YPR 19명이 3개 팀으로 나뉘어 맞붙는다. 오늘부터 모든 경기 기록이 쌓이기 시작한다.\n\nA팀은 권태홍, 김병채, 김재홍 등 7명, B팀은 김동근, 변현우, 안휘진 등 6명, C팀은 구대현, 김응철, 이민선 등 6명으로 꾸려졌다.\n\n경기 결과와 오늘의 주인공은 마감 기사에서 전한다.','sample-template','wire_prompt_v2','FIRST_APPEARANCE:first_appearance_v1','PUBLISHED',1,'2026-07-04 22:46:00.000',NULL,1,'{\"teams\": [{\"members\": [\"권태홍\", \"김병채\", \"김재홍\", \"김현섭\", \"손원일\", \"윤영문\", \"전원재\"], \"teamCode\": \"A\", \"guestCount\": 0}, {\"members\": [\"김동근\", \"변현우\", \"안휘진\", \"윤기창\", \"이채현\", \"임우철\"], \"teamCode\": \"B\", \"guestCount\": 0}, {\"members\": [\"구대현\", \"김응철\", \"이민선\", \"이용준\", \"이종훈\", \"진선호\"], \"teamCode\": \"C\", \"guestCount\": 0}], \"clubName\": \"YPR\", \"insights\": [{\"id\": 1, \"type\": \"FIRST_APPEARANCE\", \"facts\": {\"member\": {\"name\": \"손원일\", \"memberId\": 1}, \"teamCode\": \"A\", \"firstAppearance\": true}, \"subject\": {\"name\": \"손원일\", \"memberId\": 1}, \"category\": \"PLAYER\", \"importance\": 50}, {\"id\": 2, \"type\": \"FIRST_APPEARANCE\", \"facts\": {\"member\": {\"name\": \"김응철\", \"memberId\": 2}, \"teamCode\": \"C\", \"firstAppearance\": true}, \"subject\": {\"name\": \"김응철\", \"memberId\": 2}, \"category\": \"PLAYER\", \"importance\": 50}, {\"id\": 3, \"type\": \"FIRST_APPEARANCE\", \"facts\": {\"member\": {\"name\": \"안휘진\", \"memberId\": 3}, \"teamCode\": \"B\", \"firstAppearance\": true}, \"subject\": {\"name\": \"안휘진\", \"memberId\": 3}, \"category\": \"PLAYER\", \"importance\": 50}, {\"id\": 4, \"type\": \"FIRST_APPEARANCE\", \"facts\": {\"member\": {\"name\": \"전원재\", \"memberId\": 5}, \"teamCode\": \"A\", \"firstAppearance\": true}, \"subject\": {\"name\": \"전원재\", \"memberId\": 5}, \"category\": \"PLAYER\", \"importance\": 50}, {\"id\": 5, \"type\": \"FIRST_APPEARANCE\", \"facts\": {\"member\": {\"name\": \"김현섭\", \"memberId\": 6}, \"teamCode\": \"A\", \"firstAppearance\": true}, \"subject\": {\"name\": \"김현섭\", \"memberId\": 6}, \"category\": \"PLAYER\", \"importance\": 50}, {\"id\": 6, \"type\": \"FIRST_APPEARANCE\", \"facts\": {\"member\": {\"name\": \"윤기창\", \"memberId\": 7}, \"teamCode\": \"B\", \"firstAppearance\": true}, \"subject\": {\"name\": \"윤기창\", \"memberId\": 7}, \"category\": \"PLAYER\", \"importance\": 50}, {\"id\": 7, \"type\": \"FIRST_APPEARANCE\", \"facts\": {\"member\": {\"name\": \"이종훈\", \"memberId\": 8}, \"teamCode\": \"C\", \"firstAppearance\": true}, \"subject\": {\"name\": \"이종훈\", \"memberId\": 8}, \"category\": \"PLAYER\", \"importance\": 50}, {\"id\": 8, \"type\": \"FIRST_APPEARANCE\", \"facts\": {\"member\": {\"name\": \"이용준\", \"memberId\": 11}, \"teamCode\": \"C\", \"firstAppearance\": true}, \"subject\": {\"name\": \"이용준\", \"memberId\": 11}, \"category\": \"PLAYER\", \"importance\": 50}, {\"id\": 9, \"type\": \"FIRST_APPEARANCE\", \"facts\": {\"member\": {\"name\": \"변현우\", \"memberId\": 12}, \"teamCode\": \"B\", \"firstAppearance\": true}, \"subject\": {\"name\": \"변현우\", \"memberId\": 12}, \"category\": \"PLAYER\", \"importance\": 50}, {\"id\": 10, \"type\": \"FIRST_APPEARANCE\", \"facts\": {\"member\": {\"name\": \"김재홍\", \"memberId\": 13}, \"teamCode\": \"A\", \"firstAppearance\": true}, \"subject\": {\"name\": \"김재홍\", \"memberId\": 13}, \"category\": \"PLAYER\", \"importance\": 50}, {\"id\": 11, \"type\": \"FIRST_APPEARANCE\", \"facts\": {\"member\": {\"name\": \"김동근\", \"memberId\": 14}, \"teamCode\": \"B\", \"firstAppearance\": true}, \"subject\": {\"name\": \"김동근\", \"memberId\": 14}, \"category\": \"PLAYER\", \"importance\": 50}, {\"id\": 12, \"type\": \"FIRST_APPEARANCE\", \"facts\": {\"member\": {\"name\": \"이민선\", \"memberId\": 15}, \"teamCode\": \"C\", \"firstAppearance\": true}, \"subject\": {\"name\": \"이민선\", \"memberId\": 15}, \"category\": \"PLAYER\", \"importance\": 50}, {\"id\": 13, \"type\": \"FIRST_APPEARANCE\", \"facts\": {\"member\": {\"name\": \"권태홍\", \"memberId\": 16}, \"teamCode\": \"A\", \"firstAppearance\": true}, \"subject\": {\"name\": \"권태홍\", \"memberId\": 16}, \"category\": \"PLAYER\", \"importance\": 50}, {\"id\": 14, \"type\": \"FIRST_APPEARANCE\", \"facts\": {\"member\": {\"name\": \"진선호\", \"memberId\": 17}, \"teamCode\": \"C\", \"firstAppearance\": true}, \"subject\": {\"name\": \"진선호\", \"memberId\": 17}, \"category\": \"PLAYER\", \"importance\": 50}, {\"id\": 15, \"type\": \"FIRST_APPEARANCE\", \"facts\": {\"member\": {\"name\": \"임우철\", \"memberId\": 18}, \"teamCode\": \"B\", \"firstAppearance\": true}, \"subject\": {\"name\": \"임우철\", \"memberId\": 18}, \"category\": \"PLAYER\", \"importance\": 50}], \"location\": null, \"articleType\": \"PRE_MATCH\", \"sessionDate\": \"2026-07-05\", \"sessionTitle\": \"일요 정기 경기\"}','{\"body\": \"7월 5일 일요일, YPR 19명이 3개 팀으로 나뉘어 맞붙는다. 오늘부터 모든 경기 기록이 쌓이기 시작한다.\\n\\nA팀은 권태홍, 김병채, 김재홍 등 7명, B팀은 김동근, 변현우, 안휘진 등 6명, C팀은 구대현, 김응철, 이민선 등 6명으로 꾸려졌다.\\n\\n경기 결과와 오늘의 주인공은 마감 기사에서 전한다.\", \"title\": \"7월 5일, YPR 기록의 첫 페이지\", \"summary\": \"7월 5일 일요일, YPR 19명이 3개 팀으로 나뉘어 맞붙는다. 오늘부터 모든 경기 기록이 쌓이기 시작한다.\", \"usedInsightIds\": []}',NULL,'2026-07-04 22:46:00.000','2026-07-04 22:40:00.000'),(2,1,1,NULL,'SESSION_RECAP','김현섭, 종료 47초 전 결승골','6경기는 김현섭의 발끝에서 갈렸다. 종료 47초를 남기고 터진 결승골이었다.','7월 5일 YPR은 9경기를 치르며 총 36골을 기록했다. B팀이 2승 3무 1패로 가장 많은 승리를 챙겼다.\n\n득점 순위에서는 안휘진(5골), 전원재(4골), 김동근(3골) 순으로 앞섰다.\n\n6경기는 김현섭의 발끝에서 갈렸다. 종료 47초를 남기고 터진 결승골이었다. 권태홍의 패스를 전원재가 마무리한 골이 오늘만 세 번 나왔다.\n\n안휘진의 패스를 김동근이 마무리한 골이 오늘만 두 번 나왔다. 윤기창의 패스를 안휘진이 마무리한 골이 오늘만 두 번 나왔다.\n\n안휘진이 이주의 득점왕(5골)에 이름을 올렸다. 권태홍이 이주의 도움왕(5도움)에 이름을 올렸다.\n\n1경기  A 3 : 3 B\n2경기  B 0 : 2 C\n3경기  C 2 : 2 A\n4경기  A 2 : 2 B\n5경기  B 3 : 1 C\n6경기  C 3 : 4 A\n7경기  A 2 : 2 B\n8경기  B 2 : 0 C\n9경기  C 2 : 1 A','sample-template','wire_prompt_v2','ASSIST_COMBO:assist_combo_v1,LATE_WINNER:late_winner_v1,TITLE_AWARDED:title_awarded_v1','PUBLISHED',1,'2026-07-05 01:48:00.000',NULL,1,'{\"clubName\": \"YPR\", \"insights\": [{\"id\": 20, \"type\": \"LATE_WINNER\", \"facts\": {\"teamA\": \"C\", \"teamB\": \"A\", \"assist\": {\"name\": \"권태홍\", \"memberId\": 16}, \"gameNo\": 6, \"member\": {\"name\": \"김현섭\", \"memberId\": 6}, \"scoreA\": 3, \"scoreB\": 4, \"winnerTeam\": \"A\", \"remainingSec\": 47, \"inStoppageTime\": false}, \"subject\": {\"name\": \"김현섭\", \"memberId\": 6}, \"category\": \"MATCH\", \"importance\": 68}, {\"id\": 21, \"type\": \"ASSIST_COMBO\", \"facts\": {\"member\": {\"name\": \"전원재\", \"memberId\": 5}, \"scorer\": {\"name\": \"전원재\", \"memberId\": 5}, \"assister\": {\"name\": \"권태홍\", \"memberId\": 16}, \"countToday\": 3, \"careerCount\": 3}, \"subject\": {\"name\": \"전원재\", \"memberId\": 5}, \"category\": \"PAIR\", \"importance\": 60}, {\"id\": 22, \"type\": \"ASSIST_COMBO\", \"facts\": {\"member\": {\"name\": \"김동근\", \"memberId\": 14}, \"scorer\": {\"name\": \"김동근\", \"memberId\": 14}, \"assister\": {\"name\": \"안휘진\", \"memberId\": 3}, \"countToday\": 2, \"careerCount\": 2}, \"subject\": {\"name\": \"김동근\", \"memberId\": 14}, \"category\": \"PAIR\", \"importance\": 50}, {\"id\": 23, \"type\": \"ASSIST_COMBO\", \"facts\": {\"member\": {\"name\": \"안휘진\", \"memberId\": 3}, \"scorer\": {\"name\": \"안휘진\", \"memberId\": 3}, \"assister\": {\"name\": \"윤기창\", \"memberId\": 7}, \"countToday\": 2, \"careerCount\": 2}, \"subject\": {\"name\": \"안휘진\", \"memberId\": 3}, \"category\": \"PAIR\", \"importance\": 50}, {\"id\": 24, \"type\": \"TITLE_AWARDED\", \"facts\": {\"tied\": false, \"value\": 5, \"member\": {\"name\": \"안휘진\", \"memberId\": 3}, \"metric\": \"goals\", \"periodEnd\": \"2026-07-05\", \"titleName\": \"이주의 득점왕\", \"periodStart\": \"2026-06-29\"}, \"subject\": {\"name\": \"안휘진\", \"memberId\": 3}, \"category\